<section><div class="page-heading"><div><p class="eyebrow">Commercial configuration</p><h1>Plans</h1><p class="muted">Prices, features, and limits are database-configured and enforced server-side.</p></div></div><div class="admin-plan-grid"><?php foreach($plans as$plan):?><article class="panel"><header><div><span class="badge <?= $plan['is_active']?'active':'inactive' ?>"><?= $plan['is_active']?'ACTIVE':'INACTIVE' ?></span><h2><?= e($plan['name']) ?></h2><code><?= e($plan['code']) ?></code></div><strong><?= e($plan['currency_code']) ?> <?= e($plan['monthly_price']) ?><small>/ month</small></strong></header><p><?= e($plan['description']??'No description') ?></p><dl class="admin-definition"><div><dt>Subscriptions</dt><dd><?= e($plan['subscription_count']) ?> total · <?= e($plan['active_subscription_count']??0) ?> active/trial</dd></div><div><dt>Products</dt><dd><?= (int)($plan['limits']['products']??-1)<0?'Unlimited':e($plan['limits']['products']) ?></dd></div><div><dt>Categories</dt><dd><?= (int)($plan['limits']['categories']??-1)<0?'Unlimited':e($plan['limits']['categories']) ?></dd></div><div><dt>Public</dt><dd><?= $plan['is_public']?'Yes':'No' ?></dd></div></dl><a class="button secondary" href="/sa/plans/<?= e($plan['id']) ?>">Edit configuration</a></article><?php endforeach ?></div></section>
